value.string:
{\n
  "type": "function",\n
  "function": {\n
    "name": "ERP5Site_createPurchaseOrder",\n
    "description": "Create a draft purchase order. Defaults to a dry run: set dry_run=false only once you are ready to actually create it.",\n
    "parameters": {\n
      "type": "object",\n
      "properties": {\n
        "supplier_id": {\n
          "type": "string",\n
          "description": "organisation_module/... id"\n
        },\n
        "currency": {\n
          "type": "string",\n
          "enum": [\n
            "EUR",\n
            "USD"\n
          ]\n
        },\n
        "lines": {\n
          "type": "array",\n
          "items": {\n
            "type": "object",\n
            "properties": {\n
              "description": {\n
                "type": "string"\n
              },\n
              "quantity": {\n
                "type": "number"\n
              },\n
              "price": {\n
                "type": "number"\n
              }\n
            },\n
            "required": [\n
              "description",\n
              "quantity"\n
            ]\n
          }\n
        },\n
        "dry_run": {\n
          "type": "boolean",\n
          "description": "If true (default), do not create anything: just return a preview/summary of what would be created. Set to false to actually create the purchase order."\n
        }\n
      },\n
      "required": [\n
        "supplier_id",\n
        "currency",\n
        "lines"\n
      ]\n
    }\n
  }\n
}\n
